before:
import { test, expect } from "@playwright/test";

test.describe("Authentification utilisateur", () => {
  test("Failed login with invalid credentials", async ({ page }) => {
    // Given the user is on the login page
    await page.goto("https://teskerti.tn/user/login");

    // When the user enters "wrong@test.com" in the email field
    await page.locator("input[name=\"email\"]").fill("wrong@test.com");

    // And the user enters "" in the password field
    await page.locator("input[name=\"password\"]").fill("");

    // And the user submits the login form
    await page.locator("button:has-text(\"Se connecter\")").click();

    // Then an error message should be displayed
    await expect(
      page.locator(".alert, .error, [role=\"alert\"], .flash, .message").first()
    ).toBeVisible();
  });
});

